/bin/bash -lc "python - <<'PY'
import os, json
from bioblend.galaxy import GalaxyInstance
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
gi=GalaxyInstance('https://usegalaxy.org', key=key)
t=gi.tools.show_tool('toolshed.g2.bx.psu.edu/repos/iuc/filter_tabular/filter_tabular/3.3.1', io_details=True, link_details=False)
# walk inputs to print cases names and expression-related blocks
def walk(x, path=''):
    if isinstance(x, dict):
        if x.get('model_class') in ('ConditionalWhen','Conditional','Repeat') or x.get('name') in ('filter','filter_condition','expression','cond','column','operator','value'):
            nm=x.get('name', x.get('value',''))
            print('\\nPATH', path, 'CLASS', x.get('model_class'), 'NAME/VALUE', nm)
            slim={k:v for k,v in x.items() if k in ('name','type','value','label','optional','cases','inputs','options')}
            # avoid huge nested print for cases
            if 'cases' in slim: slim['cases']=[c.get('value') for c in slim['cases']]
            if 'inputs' in slim: slim['inputs']=[i.get('name', i.get('value')) for i in slim['inputs']]
            print(json.dumps(slim, indent=2)[:3000])
        for k,v in x.items(): walk(v, path+'/'+str(k))
    elif isinstance(x, list):
        for i,v in enumerate(x): walk(v, path+f'[{i}]')
walk(t.get('inputs'))
PY"

